
(function init() {
    if (!window.Spicetify?.Topbar?.Button ||
        !window.Spicetify?.LocalStorage) {
        setTimeout(init, 100);
        return;
    }

    const storage = Spicetify.LocalStorage;
    const sounds = [];

    // Create the settings panel
    const panel = document.createElement("div");

    panel.style.cssText = `
        position: fixed;
        top: 85px;
        left: 20px;
        width: 260px;
        max-height: 75vh;
        overflow-y: auto;
        padding: 20px;
        background: #242424;
        color: white;
        border-radius: 12px;
        box-shadow: 0 8px 25px #0008;
        z-index: 99999;
        display: none;
    `;

    panel.innerHTML = `
    <h3 style="margin-top:0">Settings</h3>

    <button id="stop-all" style="
        width: 100%;
        padding: 10px;
        margin-bottom: 15px;
        background: #b3261e;
        color: white;
        border: none;
        border-radius: 6px;
        cursor: pointer;
        font-weight: bold;
    ">
        Stop All Sounds
    </button>
`;
    document.body.appendChild(panel);

    // Automatically create a new ambient sound
    function createAmbientSound(id, name, audioURL) {

        // Create audio player
        const audio = new Audio();
        audio.loop = true;

        if (audioURL.startsWith("data:audio/") ||
            audioURL.startsWith("https://") ||
            audioURL.startsWith("blob:")) {
            audio.src = audioURL;
        }

        // Load saved settings
        const savedVolume = storage.get(id + "Volume");
        const parsedVolume = Number(savedVolume);

        let volume = savedVolume !== null &&
            Number.isFinite(parsedVolume)
            ? Math.max(0, Math.min(100, parsedVolume))
            : 25;

        let enabled = storage.get(id + "Enabled") !== "false";

        audio.volume = volume / 100;

        // Create settings HTML
        const section = document.createElement("div");

        section.innerHTML = `
            <h2>${name} Settings</h2>

            <p>
                <label>
                    <input type="checkbox"
                           id="${id}-enabled"
                           ${enabled ? "checked" : ""}>
                    Enable ${name}
                </label>
            </p>

            <p>
                ${name} Volume:
                <span id="${id}-value">${volume}%</span>
            </p>

            <input type="range"
                   id="${id}-volume"
                   min="0"
                   max="100"
                   value="${volume}"
                   style="width:100%;accent-color:#1db954">
        `;

        panel.appendChild(section);

        // Get controls
        const slider = section.querySelector(`#${id}-volume`);
        const volumeText = section.querySelector(`#${id}-value`);
        const checkbox = section.querySelector(`#${id}-enabled`);

        // Start or stop audio
        async function syncSound() {
            if (!enabled || !audio.src) {
                audio.pause();
                return;
            }

            if (!audio.paused) return;

            try {
                await audio.play();
            } catch (error) {
                console.error(`${name} playback failed:`, error);
                Spicetify.showNotification(
                    `${name} playback failed!`, true
                );
            }
        }

        // Volume slider
        slider.addEventListener("input", () => {
            volume = Number(slider.value);

            audio.volume = volume / 100;
            volumeText.textContent = volume + "%";

            // Save volume
            storage.set(id + "Volume", String(volume));
        });

        // Enable/disable checkbox
        checkbox.addEventListener("change", () => {
            enabled = checkbox.checked;

            // Save enabled setting
            storage.set(id + "Enabled", String(enabled));

            syncSound();
        });

        // Store the sound controller
        sounds.push({ id, name, audio, syncSound });
    }

    // ADD YOUR SOUNDS HERE
        createAmbientSound("airplane", "Airplane", "data:audio/mpeg;base64,");
    createAmbientSound("birds", "Birds", "data:audio/mpeg;base64,");
    createAmbientSound("brown-noise", "Brown Noise", "data:audio/mpeg;base64,");
    createAmbientSound("campfire", "Campfire", "data:audio/mpeg;base64,");
    createAmbientSound("city_traffic", "City Traffic", "data:audio/mpeg;base64,");
    createAmbientSound("deepspace", "Deepspace", "data:audio/mpeg;base64,");
    createAmbientSound("fan", "Fan", "data:audio/mpeg;base64,");
    createAmbientSound("fireplace", "Fireplace", "data:audio/mpeg;base64,");
    createAmbientSound("forest_night", "Forest Night", "data:audio/mpeg;base64,");
    createAmbientSound("keyboard", "Keyboard", "data:audio/mpeg;base64,");
    createAmbientSound("people_talk_inside", "People Talk Inside", "data:audio/mpeg;base64,");
    createAmbientSound("pink-noise", "Pink Noise", "data:audio/mpeg;base64,");
    createAmbientSound("Rain", "Rain", "data:audio/mpeg;base64,");
    createAmbientSound("rain_city", "Rain City", "data:audio/mpeg;base64,");
    createAmbientSound("rain_forest", "Rain Forest", "data:audio/mpeg;base64,");
    createAmbientSound("river", "River", "data:audio/mpeg;base64,");
    createAmbientSound("snow", "Snow", "data:audio/mpeg;base64,");
    createAmbientSound("summer_storm", "Summer Storm", "data:audio/mpeg;base64,");
    createAmbientSound("thunders", "Thunders", "data:audio/mpeg;base64,");
    createAmbientSound("train", "Train", "data:audio/mpeg;base64,");
    createAmbientSound("underwater", "Underwater", "data:audio/mpeg;base64,");
    createAmbientSound("waves", "Waves", "data:audio/mpeg;base64,");
    createAmbientSound("white-noise", "White Noise", "data:audio/mpeg;base64,");
    createAmbientSound("wind", "Wind", "data:audio/mpeg;base64,");
    createAmbientSound("window_rain", "Window Rain", "data:audio/mpeg;base64,");


    // Stop all ambient sounds
    panel.querySelector("#stop-all").addEventListener("click", () => {
        sounds.forEach(sound => {
            sound.audio.pause();

            // Uncheck the sound's checkbox
            const checkbox = panel.querySelector(
                `#${sound.id}-enabled`
            );
            checkbox.checked = false;

            // Trigger the existing handler so the setting is saved
            checkbox.dispatchEvent(new Event("change"));
        });

        Spicetify.showNotification("All sounds stopped!");
    });

    
    // Spotify topbar button
    new Spicetify.Topbar.Button("Atmosphere", "play", () => {
        panel.style.display =
            panel.style.display === "none" ? "block" : "none";

        if (panel.style.display === "block") {
            sounds.forEach(sound => sound.syncSound());
        }
    });

})();
